"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";

// Строгий, компактный, понятный рефакторинг сцены.
// - Вынесены константы и вспомогательные функции
// - Общая логика загрузки тайлов сделана универсальной для любого лоадера
// - Добавлен рендеринг воды (river/water layer)
// - Чистая остановка / освобождение ресурсов

const WGS84 = "EPSG:4326";
const WEB_MERCATOR = "EPSG:3857";

const TILE = {
  sizeDeg: 0.05, // ~5.5km на экваторе
  viewRadius: 5, // загружаем (2*viewRadius+1)^2 тайлов
};

const DEFAULTS = {
  startLon: parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0"),
  startLat: parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0"),
};

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function buildTileKey(x, y) {
  return `${x}_${y}`;
}

export default function ThreeScene({ settings }) {
  const containerRef = useRef(null);
  const [status, setStatus] = useState({});
  const loadersRef = useRef({});
  const acRef = useRef(null); // AbortController for current update
  const isMounted = useRef(true);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Renderer, camera, controls
    const renderer = createRenderer(container);
    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = 60;
    camera.updateProjectionMatrix();

    const controls = createControls(camera, renderer.domElement);

    // center in WebMercator
    const [centerX, centerZ] = proj4(WGS84, WEB_MERCATOR, [DEFAULTS.startLon, DEFAULTS.startLat]);

    camera.position.set(0, 800, 800);
    camera.lookAt(0, 0, 0);
    controls.target.set(0, 0, 0);
    controls.update();

    // Scene
    const { scene, cube } = createScene();
    scene.background = new THREE.Color(0xbfd9ff);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight.position.set(1000, 2000, 1000);
    scene.add(dirLight);

    const ambLight = new THREE.AmbientLight(0x666666, 0.8);
    scene.add(ambLight);

    const cleanupRaycast = setupRaycast(renderer.domElement, camera, scene, controls, container);

    // generic loader factory
    function createLayerLoader({ url, prefix, layerType }) {
      const l = new ChunkLoader(scene, {
        url,
        centerOffset: [centerX, centerZ],
        layerType,
        onProgress: (meta) => {
          setStatus((s) => ({ ...s, [prefix.replace(/_$/, "")]: meta.rendered || 0, lastQueryMs: meta.queryTimeMs || s.lastQueryMs }));
        },
      });
      return { loader: l, prefix };
    }

    // instantiate loaders: buildings, roads, rivers(water)
    // NOTE: backend endpoints — оставил прежние пути: /chunk/buildings, /chunk/roads, /chunk/water
    // ChunkLoader expects layerType keys that match its internal registry ("buildings","roads","rivers")
    const buildings = createLayerLoader({ url: "/chunk/buildings", prefix: "buildings_", layerType: "buildings" });
    const roads = createLayerLoader({ url: "/chunk/roads", prefix: "roads_", layerType: "roads" });
    const water = createLayerLoader({ url: "/chunk/water", prefix: "rivers_", layerType: "rivers" });

    loadersRef.current = { buildings, roads, water };

    // ground
    const groundGeom = new THREE.PlaneGeometry(500000, 500000, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0xf0f0f0, roughness: 1, metalness: 0 });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    // camera-follow loop
    let frame = null;
    function animate() {
      cube.rotation.y += 0.005;
      ground.position.x = camera.position.x;
      ground.position.z = camera.position.z;
      controls.update();
      renderer.render(scene, camera);
      frame = requestAnimationFrame(animate);
    }
    animate();

    // tile loading logic (universal)
    let loading = false;
    let debounceTimer = null;

    function getVisibleTilesForTarget(targetX, targetZ) {
      const [lon, lat] = proj4(WEB_MERCATOR, WGS84, [targetX + centerX, targetZ + centerZ]);
      const tileX = Math.floor(lon / TILE.sizeDeg);
      const tileY = Math.floor(lat / TILE.sizeDeg);
      const tiles = [];
      const active = new Set();

      for (let dx = -TILE.viewRadius; dx <= TILE.viewRadius; dx++) {
        for (let dy = -TILE.viewRadius; dy <= TILE.viewRadius; dy++) {
          const x = tileX + dx;
          const y = tileY + dy;
          const minLon = x * TILE.sizeDeg;
          const minLat = y * TILE.sizeDeg;
          const maxLon = (x + 1) * TILE.sizeDeg;
          const maxLat = (y + 1) * TILE.sizeDeg;
          const key = buildTileKey(x, y);
          tiles.push({ minLon, minLat, maxLon, maxLat, key });
          active.add(key);
        }
      }

      return { tiles, active };
    }

    async function loadVisibleTiles() {
      if (loading) return;
      loading = true;

      const { tiles, active } = getVisibleTilesForTarget(controls.target.x, controls.target.z);

      // abort previous
      if (acRef.current) acRef.current.abort();
      acRef.current = new AbortController();
      const signal = acRef.current.signal;

      try {
        // for each tile, load each layer in parallel but avoid waiting for water to block buildings/roads
        await Promise.all(
          tiles.map((tile) =>
            Promise.allSettled([
              loadersRef.current.buildings.loader.loadChunk(tile.minLon, tile.minLat, tile.maxLon, tile.maxLat, { simplify: 2.0, signal, useCache: true, keyHint: `buildings_${tile.key}` }),
              loadersRef.current.roads.loader.loadChunk(tile.minLon, tile.minLat, tile.maxLon, tile.maxLat, { simplify: 0.5, signal, useCache: true, keyHint: `roads_${tile.key}` }),
              loadersRef.current.water.loader.loadChunk(tile.minLon, tile.minLat, tile.maxLon, tile.maxLat, { simplify: 0.8, signal, useCache: true, keyHint: `rivers_${tile.key}` }),
            ])
          )
        );

        // evict tiles not in active set for each loader
        for (const { loader, prefix } of Object.values(loadersRef.current)) {
          for (const key of Array.from(loader.meshGroups.keys())) {
            // keys saved by ChunkLoader will be exactly the keyHint we passed (with prefix)
            const m = key.replace(new RegExp(`^${prefix}`), "");
            if (!active.has(m)) loader.removeChunk(key);
          }
        }
      } catch (e) {
        if (e.name === "AbortError") {
          // fine, new request superseded old
          console.warn("[Scene] update aborted");
        } else {
          console.error("[Scene] loadVisibleTiles error:", e);
        }
      } finally {
        loading = false;
      }
    }

    const debouncedUpdate = () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(loadVisibleTiles, 250);
    };

    controls.addEventListener("change", debouncedUpdate);
    // initial load
    loadVisibleTiles();

    // resize
    function onResize() {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    }
    window.addEventListener("resize", onResize);

    // cleanup
    return () => {
      isMounted.current = false;
      if (frame) cancelAnimationFrame(frame);
      clearTimeout(debounceTimer);
      controls.removeEventListener("change", debouncedUpdate);
      window.removeEventListener("resize", onResize);
      if (acRef.current) acRef.current.abort();

      // dispose loaders
      for (const { loader } of Object.values(loadersRef.current)) loader.clearAll();

      cleanupRaycast();

      // DOM + three cleanup
      if (renderer.domElement && container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
      renderer.dispose();

      cube.geometry?.dispose();
      if (Array.isArray(cube.material)) cube.material.forEach((m) => m.dispose());
      else cube.material?.dispose();

      groundGeomCleanup(scene);
    };

    // helper local cleanup that ensures ground geometry is disposed
    function groundGeomCleanup(s) {
      // attempt to find ground by its material color (best-effort)
      s.traverse((n) => {
        if (n.isMesh) {
          n.geometry?.dispose();
          if (Array.isArray(n.material)) n.material.forEach((m) => m.dispose());
          else n.material?.dispose();
        }
      });
    }
  }, []);

  return (
    <div className="w-full h-full relative">
      <div ref={containerRef} className="w-full h-full" />
    </div>
  );
}
